func (r *BackupReconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
    var b datav1.Backup
    if err := r.Get(ctx, req.NamespacedName, &b); err != nil {
        // Deleted before we got here: nothing to do.
        return ctrl.Result{}, client.IgnoreNotFound(err)
    }

    // 1. Observe actual state: does the CronJob exist?
    var cj batchv1.CronJob
    err := r.Get(ctx, types.NamespacedName{Namespace: b.Namespace, Name: b.Name}, &cj)

    // 2. Diff and act: create it, owned by the Backup, if missing.
    if apierrors.IsNotFound(err) {
        cj = desiredCronJob(&b)
        ctrl.SetControllerReference(&b, &cj, r.Scheme)
        if err := r.Create(ctx, &cj); err != nil {
            return ctrl.Result{}, err          // retried with backoff
        }
    } else if err != nil {
        return ctrl.Result{}, err
    }

    // 3. Report observed state back in .status
    b.Status.Phase = "Scheduled"
    if err := r.Status().Update(ctx, &b); err != nil {
        return ctrl.Result{}, err
    }
    return ctrl.Result{RequeueAfter: 10 * time.Minute}, nil   // periodic resync
}
